import zipfile
import re
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
      'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}

path = 'sales_data.xlsx'
z = zipfile.ZipFile(path)
print('Files:', [n for n in z.namelist() if 'worksheets' in n or 'workbook' in n or 'sharedStrings' in n])

wb = ET.fromstring(z.read('xl/workbook.xml'))
rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
rid_to_target = {r.get('Id'): r.get('Target') for r in rels}
sheet_rids = [(s.get('name'), s.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')) for s in wb.find('m:sheets', NS)]

shared = []
if 'xl/sharedStrings.xml' in z.namelist():
    ss = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in ss.findall('m:si', NS):
        shared.append(''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')))

def col_letter(ref):
    return re.match(r'[A-Z]+', ref).group(0)

for name, rid in sheet_rids:
    target = rid_to_target[rid].lstrip('/')
    if not target.startswith('xl/'):
        target = 'xl/' + target
    root = ET.fromstring(z.read(target))
    rows = []
    for row in root.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row'):
        cells = {}
        for c in row.findall('m:c', NS):
            ref = c.get('r'); t = c.get('t'); v = c.find('m:v', NS)
            val = v.text if v is not None else ''
            if t == 's' and val != '':
                val = shared[int(val)]
            cells[col_letter(ref)] = val
        rows.append(cells)
    print(f'--- sheet={name} rows={len(rows)}')
    for i, r in enumerate(rows[:6], 1):
        print(i, r)

